    def _root_service_group_id(self):
        # The tenant root service group's name is the tenant ID. Scrub the real tenant ID
        # from recordings so the replay (mocked profile) produces the same URLs/bodies.
        tenant_id = self.cmd('account show').get_output_in_json()['tenantId']
        if self._is_recording() and tenant_id != MOCKED_TENANT_ID:
            self.name_replacer.register_name_pair(tenant_id, MOCKED_TENANT_ID)
        return '/providers/Microsoft.Management/serviceGroups/' + tenant_id

    def _create_service_group(self, timeout_seconds=600):
        """Create a test service group under the tenant root and wait until it is Succeeded."""
        self.kwargs.update({
            'sg_body': json.dumps({
                'properties': {
                    'displayName': self.kwargs['sg_name'],
                    'parent': {'resourceId': self._root_service_group_id()},
                }
            }),
        })
        self.cmd('az rest --method put '
                 '--url /providers/Microsoft.Management/serviceGroups/{sg_name}?api-version={sg_api} '
                 "--body '{sg_body}'")

        # PUT is long-running (201 + Azure-AsyncOperation) and az rest doesn't poll, so poll the
        # resource. GET returns 404 ResourceNotFound until the group has been materialised.
        deadline = time.time() + timeout_seconds
        while True:
            try:
                state = self.cmd('az rest --method get '
                                 '--url /providers/Microsoft.Management/serviceGroups/{sg_name}?api-version={sg_api}'
                                 ).get_output_in_json()['properties'].get('provisioningState')
            except HTTPError as ex:
                if 'ResourceNotFound' not in str(ex):
                    raise
                state = 'NotFoundYet'
            if state == 'Succeeded':
                return
            if state in ('Failed', 'Canceled') or time.time() > deadline:
                self.fail('Service group {} did not provision (state: {})'.format(self.kwargs['sg_name'], state))
            time.sleep(15)  # patched to a no-op during playback by the testsdk

    def _cmd_after_rbac_propagation(self, command, checks=None, attempts=10, delay_seconds=30):
        """Run a service-group-scoped command, retrying while the creator's role assignment propagates.

        The creator of a service group is made its Service Group Administrator automatically, but the
        assignment can take minutes to reach every RP, so reads under the new group may return 403.
        """
